def run_stabilization(config: TestRunnerConfig, tests, new_tests):
    """Rerun tests to detect flakiness after the initial run.

    ``new_tests`` is the list of newly added tests when ``--changed-tests`` is
    active (``None`` otherwise). Returns the number of stabilization reruns that
    reported a non-zero exit code.
    """
    rerun_failures = 0

    def account(result):
        nonlocal rerun_failures
        if result is not None and result.returncode != 0:
            rerun_failures += 1

    if new_tests is not None:
        if len(new_tests) > CHANGED_TESTS_WHOLE_SET_THRESHOLD:
            # Too many new tests to rerun individually: rerun the whole new-test
            # set a fixed number of additional times instead.
            print(
                f"stabilizing {len(new_tests)} new tests with "
                f"{CHANGED_TESTS_WHOLE_SET_RERUNS} additional runs of the new-test set"
            )
            new_batches = list(chunked(new_tests, compute_batch_size(len(new_tests), config)))
            for _ in range(CHANGED_TESTS_WHOLE_SET_RERUNS):
                if stop_requested():
                    return rerun_failures
                result = run_tests(config, new_batches, len(new_tests))
                if result is not None and result.returncode == 130:
                    return rerun_failures
                account(result)
            return rerun_failures
        tests_to_stabilize = new_tests
        print(f"stabilizing {len(tests_to_stabilize)} new tests individually")
    else:
        tests_to_stabilize = tests
        print(f"stabilizing {len(tests_to_stabilize)} tests individually")

    for test in tests_to_stabilize:
        for _ in range(rerun_count_for(test)):
            if stop_requested():
                return rerun_failures
            result = run_tests(config, [[test.name]], 1)
            if result is not None and result.returncode == 130:
                return rerun_failures
            account(result)
    return rerun_failures


